def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(r"\s*(<=|>=|<>|[A-Z]+[0-9]+|[A-Z]+|[0-9]+|.)")
    values = {}
    active = set()

    def parse(content):
        tokens = token_pattern.findall(content[1:])
        pos = 0

        def expression():
            nonlocal pos
            node = term()
            while pos < len(tokens) and tokens[pos] in ("+", "-"):
                op = tokens[pos]
                pos += 1
                node = (op, node, term())
            return node

        def term():
            nonlocal pos
            node = unary()
            while pos < len(tokens) and tokens[pos] in ("*", "/"):
                op = tokens[pos]
                pos += 1
                node = (op, node, unary())
            return node

        def unary():
            nonlocal pos
            count = 0
            while tokens[pos] == "-":
                count += 1
                pos += 1
            node = atom()
            return ("neg", node) if count % 2 else node

        def atom():
            nonlocal pos
            token = tokens[pos]
            pos += 1

            if token.isdigit():
                return ("int", int(token))

            if token == "(":
                node = expression()
                pos += 1
                return node

            if token in ("SUM", "MIN", "MAX"):
                pos += 1
                args = []
                while True:
                    if pos + 1 < len(tokens) and tokens[pos + 1] == ":":
                        start = tokens[pos]
                        end = tokens[pos + 2]
                        pos += 3
                        args.append(("range", start, end))
                    else:
                        args.append(expression())
                    if tokens[pos] == ")":
                        pos += 1
                        break
                    pos += 1
                return (token, args)

            if token == "IF":
                pos += 1
                left = expression()
                op = tokens[pos]
                pos += 1
                right = expression()
                pos += 1
                then = expression()
                pos += 1
                otherwise = expression()
                pos += 1
                return ("IF", op, left, right, then, otherwise)

            return ("cell", token)

        return expression()

    def evaluate_cell(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in active:
            return "#CYCLE!"

        active.add(name)
        content = cells[name]
        if content.startswith("="):
            result = yield ("eval", parse(content))
        else:
            result = int(content)
        active.remove(name)
        values[name] = result
        return result

    def evaluate(node):
        kind = node[0]

        if kind == "int":
            return node[1]
        if kind == "cell":
            return (yield ("cell", node[1]))
        if kind == "neg":
            value = yield ("eval", node[1])
            return value if isinstance(value, str) else -value

        if kind in ("+", "-", "*", "/"):
            left = yield ("eval", node[1])
            if isinstance(left, str):
                return left
            right = yield ("eval", node[2])
            if isinstance(right, str):
                return right
            if kind == "+":
                return left + right
            if kind == "-":
                return left - right
            if kind == "*":
                return left * right
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient

        if kind == "IF":
            left = yield ("eval", node[2])
            if isinstance(left, str):
                return left
            right = yield ("eval", node[3])
            if isinstance(right, str):
                return right
            op = node[1]
            condition = {
                "=": left == right,
                "<>": left != right,
                "<": left < right,
                "<=": left <= right,
                ">": left > right,
                ">=": left >= right,
            }[op]
            return (yield ("eval", node[4] if condition else node[5]))

        result = None
        for arg in node[1]:
            if arg[0] == "range":
                start, end = arg[1], arg[2]
                first_col = min(ord(start[0]), ord(end[0]))
                last_col = max(ord(start[0]), ord(end[0]))
                first_row = min(int(start[1:]), int(end[1:]))
                last_row = max(int(start[1:]), int(end[1:]))
                for row in range(first_row, last_row + 1):
                    for col in range(first_col, last_col + 1):
                        name = chr(col) + str(row)
                        if name not in cells:
                            continue
                        value = yield ("cell", name)
                        if isinstance(value, str):
                            return value
                        if result is None:
                            result = value
                        elif kind == "SUM":
                            result += value
                        elif kind == "MIN":
                            result = min(result, value)
                        else:
                            result = max(result, value)
            else:
                value = yield ("eval", arg)
                if isinstance(value, str):
                    return value
                if result is None:
                    result = value
                elif kind == "SUM":
                    result += value
                elif kind == "MIN":
                    result = min(result, value)
                else:
                    result = max(result, value)
        return 0 if result is None else result

    def run(name):
        stack = [evaluate_cell(name)]
        result = None
        while stack:
            try:
                request = stack[-1].send(result)
                result = None
                if request[0] == "cell":
                    stack.append(evaluate_cell(request[1]))
                else:
                    stack.append(evaluate(request[1]))
            except StopIteration as finished:
                stack.pop()
                result = finished.value
        return result

    for name in cells:
        if name not in values:
            run(name)

    return {name: values[name] for name in cells}
